template <typename T, size_t N>
constexpr T arraySum(const T (&arr)[N]) {
  T sum = 0;
  for (size_t i = 0; i < N; ++i) {
    sum += arr[i];
  }
  return sum;
}

int main() {
  constexpr int arr[] = {1, 2, 3, 4, 5};
  constexpr int sum = arraySum(arr); // Compile-time calculation
  std::cout << sum << std::endl; // Output: 15
  return 0;
}
